import{_ as t,o as d,c as o,ah as r}from"./chunks/framework.rk_qxSDs.js";const u=JSON.parse('{"title":"Query Configuration","description":"Options of the query plugin and the qs parse options.","frontmatter":{"title":"Query Configuration","description":"Options of the query plugin and the qs parse options.","relatedPlugins":["basic"]},"headers":[],"relativePath":"query/configuration.md","filePath":"query/configuration.md","lastUpdated":1794920275000}'),a={name:"query/configuration.md"};function c(i,e,n,s,h,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>query(options?)</code> takes one object, the <code>Options</code> type.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>parse</code></td><td><code>ParseOptions</code></td><td>none</td><td>Passed to qs <code>parse</code> unchanged</td></tr></tbody></table><h3 id="parse" tabindex="-1"><code>parse</code> <a class="header-anchor" href="#parse" aria-label="Permalink to &quot;`parse`&quot;">​</a></h3><p>The qs <code>IParseOptions</code>. The common ones, with the defaults of qs 6:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>depth</code></td><td><code>number | false</code></td><td><code>5</code></td><td>Maximum nesting depth of bracket keys; deeper keys stay in the key string</td></tr><tr><td><code>arrayLimit</code></td><td><code>number</code></td><td><code>20</code></td><td>Largest array qs builds: an index of <code>arrayLimit</code> or more (<code>a[20]=x</code>), or more than <code>arrayLimit</code> repeated keys, gives an object with numeric keys</td></tr><tr><td><code>parameterLimit</code></td><td><code>number</code></td><td><code>1000</code></td><td>Maximum number of parameters parsed; the rest are dropped</td></tr><tr><td><code>throwOnLimitExceeded</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Throw instead of dropping parameters over <code>parameterLimit</code> or building an object for an array index of <code>arrayLimit</code> or more; <code>depth</code> is not covered</td></tr><tr><td><code>strictDepth</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Throw when a key nests deeper than <code>depth</code></td></tr><tr><td><code>allowDots</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Read <code>a.b=c</code> like <code>a[b]=c</code></td></tr><tr><td><code>comma</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Split <code>a=b,c</code> into <code>[&#39;b&#39;, &#39;c&#39;]</code></td></tr><tr><td><code>parseArrays</code></td><td><code>boolean</code></td><td><code>true</code></td><td>With <code>false</code>, <code>a[0]=b</code> gives <code>{ a: { 0: &#39;b&#39; } }</code></td></tr><tr><td><code>duplicates</code></td><td><code>&#39;combine&#39; | &#39;first&#39; | &#39;last&#39;</code></td><td><code>&#39;combine&#39;</code></td><td>What a repeated key gives: an array, the first or the last value</td></tr><tr><td><code>decoder</code></td><td><code>function</code></td><td>qs URI decoder</td><td>Decodes keys and values; qs itself never turns a value into a number or boolean, a decoder can</td></tr></tbody></table><p>The <a href="https://github.com/ljharb/qs#parsing-objects" target="_blank" rel="noreferrer">qs documentation</a> lists the others. <a href="/query/recipes#parser-options">Parser Options</a> shows a configuration.</p><p>The middleware parses every request it runs for, so with <code>throwOnLimitExceeded</code> or <code>strictDepth</code> a query over a limit answers <code>500</code> on every route behind <code>query()</code>, also on routes that do not read it.</p>',9)])])}const f=t(a,[["render",c]]);export{u as __pageData,f as default};
